std::map<std::string, int> counts;

// 1. Insertion/Assignment
counts["apple"] = 5;

// 2. Access/Modification
counts["apple"]++;

// 3. Implicit Insertion (Default Initialization)
// If key "banana" missing, it is created (value initialized to 0).
int current_count = counts["banana"];

// count["banana"] is now 0 (and exists in map)
counts["banana"] = 10;
